11	#ifndef MATMUL_TILE_H
12	#define MATMUL_TILE_H
13	
14	#include "kernel_operator.h"
15	
16	// NOTE: These tile helpers are shared across multiple matmul template variants.
17	// This variant provides both half and int8_t overloads of LoadNzL1ToZnL0B.
18	// The LoadNdGmToNzL1, LoadNzL1ToZzL0A, and FixpipeNzL0cToNdGm helpers are
19	// identical to those in quant_matmul/kernel/matmul_tile.h and
20	// reshape_matmul_rowwise_quant_int8/kernel/matmul_tile.h — keep in sync.
21	
22	// GM(ND) -> L1(Nz)
23	// m % 16 == 0 && n % c0 == 0
24	template<typename T>
25	__aicore__ inline void LoadNdGmToNzL1(const AscendC::LocalTensor<T> &dst,
26	                                      const AscendC::GlobalTensor<T> &src,
27	                                      uint32_t m, uint32_t n, uint32_t ld)
28	{
29	    AscendC::Nd2NzParams params;
30	    params.ndNum = 1;
31	    params.nValue = m;
32	    params.dValue = n;
33	    params.srcNdMatrixStride = 0;
34	    params.srcDValue = ld;
35	    params.dstNzC0Stride = m;
36	    params.dstNzNStride = 1;
37	    params.dstNzMatrixStride = 0;
38	    AscendC::DataCopy(dst, src, params);
39	}
40	
41	// L1(Nz) -> L0A(Zz)
42	// m % 16 == 0 && k % c0 == 0
43	template<typename T>
44	__aicore__ inline void LoadNzL1ToZzL0A(const AscendC::LocalTensor<T> &dst,
45	                                       const AscendC::LocalTensor<T> &src,
46	                                       uint32_t m, uint32_t k, uint32_t colC0Stride)
47	{
48	    AscendC::LoadData3DParamsV2<T> params;
49	    params.l1H = 1;
50	    params.l1W = colC0Stride;
51	    params.channelSize = k;
52	    params.kExtension = k;
53	    params.mExtension = m;
54	    params.strideH = 1;
55	    params.strideW = 1;
56	    params.filterH = 1;
57	    params.filterW = 1;
58	    params.dilationFilterH = 1;
59	    params.dilationFilterW = 1;
60	    AscendC::LoadData(dst, src, params);
61	}
62	
63	
64	// L1(Nz) -> L0B(Zn)
65	// 参数只有k,n, 只适用于整个基本块, 支持任意2字节类型 (half, bfloat16_t, ...)
66	template<typename T>
67	__aicore__ inline void LoadNzL1ToZnL0B(const AscendC::LocalTensor<T> &dst,
68	                                       const AscendC::LocalTensor<T> &src,
69	                                       uint32_t k, uint32_t n, uint32_t colC0Stride)
70	{
71	    AscendC::LoadData3DParamsV2<T> params;
72	    params.l1H = 1;
73	    params.l1W = colC0Stride;
74	    params.channelSize = n;
75	    params.kExtension = n;
76	    params.mExtension = k;
77	    params.strideH = 1;
78	    params.strideW = 1;
79	    params.filterH = 1;
80	    params.filterW = 1;
81	    params.dilationFilterH = 1;
82	    params.dilationFilterW = 1;
83	    AscendC::LoadData(dst, src, params);
84	}
85	
86	// L1(Nz) -> L0B(Zn)
87	// 参数只有k,n, 只适用于整个基本块
88	__aicore__ inline void LoadNzL1ToZnL0B(const AscendC::LocalTensor<int8_t> &dst,
89	                                       const AscendC::LocalTensor<int8_t> &src,
90	                                       uint32_t k, uint32_t n, uint32_t colC0Stride)
91	{
92	    static constexpr uint32_t FRAC_M  = 16;
93	    static constexpr uint32_t FRAC_N  = 16;
94	    static constexpr uint32_t C0_SIZE = 32;
95	    static constexpr uint32_t FRAC_K  = C0_SIZE;
96	    uint32_t dstOffset = FRAC_K * n;
97	    uint32_t srcOffset = FRAC_K * C0_SIZE;
98	    // Nz -> Zn
99	    AscendC::LoadData2dTransposeParams loadDataParams;
100	    loadDataParams.repeatTimes = n / C0_SIZE;
101	    loadDataParams.srcStride = colC0Stride / FRAC_K;
102	    loadDataParams.dstGap = 1;
103	    loadDataParams.dstFracGap = 0;
104	    for (int i = 0; i < k / FRAC_K; ++i) {
105	        AscendC::LoadDataWithTranspose(dst[i * dstOffset], src[i * srcOffset], loadDataParams);
106	    }
107	}
108	
109	
110	
111	// L0C(Nz) -> GM(ND)
112	// 参数只有m, n，只适用于整个基本块搬出，如果不够基本块，需要补齐stride
113	template<typename T>
114	__aicore__ inline void FixpipeNzL0cToNdGm(const AscendC::GlobalTensor<T> &dst,
115	                                      const AscendC::LocalTensor<T> &src,
116	                                      uint32_t m, uint32_t n)
117	{
118	    AscendC::FixpipeParamsV220 params;
119	    params.nSize = n;
120	    params.mSize = m;
121	    params.srcStride = m;
122	    params.dstStride = n;
123	    params.ndNum = 1;
124	    params.srcNdStride = 0;
125	    params.dstNdStride = 0;
126	    AscendC::Fixpipe(dst, src, params);
127	}
128	
129	#endif // MATMUL_TILE_H
