15	__aicore__ inline uint32_t CeilDiv32(uint32_t a, uint32_t b)
16	{
17	    if (b == 0) { return 0; }
18	    return (a + b - 1) / b;
19	}
20	
21	template<typename T>
22	__aicore__ inline void CopyTiling(T *tiling, GM_ADDR tilingGM)
23	{
24	    int32_t *ptr = reinterpret_cast<int32_t *>(tiling);
25	    auto tiling32 = reinterpret_cast<__gm__ int32_t *>(tilingGM);
26	    for (size_t i = 0; i < sizeof(T) / sizeof(int32_t); ++i, ++ptr) {
27	        *ptr = *(tiling32 + i);
28	    }
29	}
30	
31	class BlockScheduler {
32	public:
33	    __aicore__ inline void Init(int M, int N, int baseM, int baseN, int numBlocks, int blockIdx)
34	    {
35	        if (baseM == 0 || baseN == 0 || numBlocks == 0) {
36	            mBlocks_ = 0;
37	            nBlocks_ = 0;
38	            startBlock_ = 0;
39	            endBlock_ = 0;
40	            current_ = 0;
41	            return;
42	        }
43	        mBlocks_ = M / baseM;
44	        nBlocks_ = N / baseN;
45	        int totalBlocks = mBlocks_ * nBlocks_;
46	        int blocksPerCore = totalBlocks / numBlocks;
47	        int remainder = totalBlocks % numBlocks;
48	        startBlock_ = blockIdx * blocksPerCore + (blockIdx < remainder ? blockIdx : remainder);
49	        endBlock_ = startBlock_ + blocksPerCore + (blockIdx < remainder ? 1 : 0);
50	        current_ = startBlock_;
51	    }
52	
53	    __aicore__ inline bool HasNext()
54	    {
55	        return current_ < endBlock_;
56	    }
57	
58	    __aicore__ inline void Next(int &mIdx, int &nIdx)
59	    {
60	        mIdx = current_ / nBlocks_;
61	        nIdx = current_ % nBlocks_;
62	        current_++;
63	    }
64	
65	private:
66	    int mBlocks_;
67	    int nBlocks_;
68	    int startBlock_;
69	    int endBlock_;
70	    int current_;
71	};
72	
