30	using namespace AscendC;
31	
32	template <typename inType, typename outType>
33	class LeakyKernel {
34	public:
35	    __aicore__ inline LeakyKernel() {}
36	    __aicore__ inline void Init(int tileM, int tileN, AscendC::TPipe *pipe);
37	    __aicore__ inline void Process(GlobalTensor<inType> &blockGM, GlobalTensor<outType> &cGlobal, int rowStride);
38	private:
39	    int tileM;
40	    int tileN;
41	    int tileSize;
42	    AscendC::LocalTensor<inType> reluInLocal;
43	    AscendC::LocalTensor<outType> reluOutLocal;
44	    AscendC::LocalTensor<outType> reluCastLocal;
45	    AscendC::TQue<AscendC::TPosition::VECIN, 0> reluInQueue_;
46	    AscendC::TQue<AscendC::TPosition::VECOUT, 0> reluOutQueue_;
47	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
48	};
49	
50	/**
51	  * @brief  Init LeakyKernel buffer and tile params.
52	  * @param  tileM: Tile row size.
53	  * @param  tileN: Tile column size.
54	  * @param  pipe: Global memory and sync management TPipe object.
55	  * @retval None
56	  */
57	template <typename inType, typename outType>
58	__aicore__ inline void LeakyKernel<inType, outType>::Init(int tileM, int tileN, AscendC::TPipe *pipe)
59	{
60	    this->tileM = tileM;
61	    this->tileN = tileN;
62	    this->tileSize = tileM * tileN;
63	    pipe->InitBuffer(reluInQueue_, 1, tileSize * sizeof(inType)); // Init output buffer.
64	    pipe->InitBuffer(reluOutQueue_, 1, tileSize * sizeof(outType)); // Init output buffer.
65	    if constexpr (!std::is_same_v<inType, outType>) {
66	        pipe->InitBuffer(castBuf_, tileSize * sizeof(outType)); // Init cast buffer.
67	    }
68	}
69	
70	/**
71	  * @brief  Read input from workspace GM, compute leakyRelu, write result to output GM.
72	  * @param  blockGM: Global tensor to read input data from (workspace slot).
73	  * @param  cGlobal: Global tensor to write output data to (with offset already applied).
74	  * @param  rowStride: Row stride of the destination matrix in elements.
75	  * @retval None
76	  */
77	template <typename inType, typename outType>
78	__aicore__ inline void LeakyKernel<inType, outType>::Process(GlobalTensor<inType> &blockGM,
79	                                                             GlobalTensor<outType> &cGlobal, int rowStride)
80	{
81	    // CopyIn
82	    reluInQueue_.AllocTensor<inType>(reluInLocal);
83	    DataCopy(reluInLocal, blockGM, tileSize);
84	    reluInQueue_.EnQue(reluInLocal);
85	
86	    // Compute
87	    reluOutQueue_.AllocTensor<outType>(reluOutLocal);
88	    reluInQueue_.DeQue<inType>(reluInLocal);
89	    if constexpr (!std::is_same_v<inType, outType>) {
90	        Cast(reluCastLocal, reluInLocal, RoundMode::CAST_ROUND, tileSize);
91	        PipeBarrier<PIPE_V>();
92	    } else {
93	        reluCastLocal = reluInLocal.template ReinterpretCast<outType>();
94	    }
95	    LeakyRelu(reluOutLocal, reluCastLocal, (outType)0.001, tileSize);
96	    reluInQueue_.FreeTensor(reluInLocal);
97	    reluOutQueue_.EnQue(reluOutLocal);
98	
99	    // CopyOut
100	    reluOutQueue_.DeQue<outType>(reluOutLocal);
101	    AscendC::DataCopyParams copyParam = {
102	        (uint16_t)tileM,
103	        (uint16_t)(tileN * sizeof(outType) / AscendC::DEFAULT_C0_SIZE),
104	        0,
105	        (uint16_t)((rowStride - tileN) * sizeof(outType) / AscendC::DEFAULT_C0_SIZE)
106	    };
107	    DataCopy(cGlobal, reluOutLocal, copyParam);
108	    reluOutQueue_.FreeTensor(reluOutLocal);
109	}
