/**
 * @file mul_addn.cpp
 * @brief MulAddn kernel: out = sum_i(matmul(x1[i], x2[i])), x1[i]:[B,K,1], x2[i]:[B,1,N]
 *
 * Uses Vector-only approach since inner dimension is 1, making Cube path
 * inefficient (padded K from 1 to 16 wastes 15/16 of Mma capacity).
 *
 * Tiling: split B across cores, each core iterates K-tiles and N-tiles,
 * accumulating n outer products per tile in float32, then casting to output dtype.
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t TILE_K = 64;
constexpr int32_t TILE_N = 64;
constexpr int32_t BUFFER_NUM = 2;

#pragma pack(push, 8)
struct MulAddnTiling {
    int32_t B;
    int32_t K;
    int32_t N;
    int32_t n;
    int32_t chunkB;
};
#pragma pack(pop)

__aicore__ inline void CopyMulAddnTiling(MulAddnTiling *tiling, GM_ADDR tilingGM) {
    int32_t *ptr = reinterpret_cast<int32_t *>(tiling);
    auto tiling32 = reinterpret_cast<__gm__ int32_t *>(tilingGM);
    for (size_t i = 0; i < sizeof(MulAddnTiling) / sizeof(int32_t); ++i, ++ptr) {
        *ptr = *(tiling32 + i);
    }
}

template <typename T>
class KernelMulAddn {
public:
    __aicore__ inline KernelMulAddn() {}
    __aicore__ inline void Init(GM_ADDR x1, GM_ADDR x2, GM_ADDR out,
                                 GM_ADDR tilingGM, AscendC::TPipe *pipe);
    __aicore__ inline void Process();

private:
    __aicore__ inline void ComputeTile(int32_t b, int32_t k0, int32_t n0,
                                        int32_t curK, int32_t curN);

    AscendC::GlobalTensor<T> x1Gm_, x2Gm_, outGm_;
    MulAddnTiling tiling_;
    AscendC::TPipe *pipe_;
    int32_t coreStartB_, KBlocks_, NBlocks_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> x1Fp32Buf_, x2Fp32Buf_, tmpBuf_, accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
};

template <typename T>
__aicore__ inline void KernelMulAddn<T>::Init(GM_ADDR x1, GM_ADDR x2, GM_ADDR out,
                                               GM_ADDR tilingGM, AscendC::TPipe *pipe) {
    pipe_ = pipe;
    CopyMulAddnTiling(&tiling_, tilingGM);

    int64_t x1Total = static_cast<int64_t>(tiling_.n) * tiling_.B * tiling_.K;
    int64_t x2Total = static_cast<int64_t>(tiling_.n) * tiling_.B * tiling_.N;
    int64_t outTotal = static_cast<int64_t>(tiling_.B) * tiling_.K * tiling_.N;

    x1Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x1), x1Total);
    x2Gm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x2), x2Total);
    outGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(out), outTotal);

    int32_t coreIdx = AscendC::GetBlockIdx();
    coreStartB_ = coreIdx * tiling_.chunkB;
    KBlocks_ = (tiling_.K + TILE_K - 1) / TILE_K;
    NBlocks_ = (tiling_.N + TILE_N - 1) / TILE_N;

    int32_t maxTile = (TILE_K > TILE_N) ? TILE_K : TILE_N;
    pipe->InitBuffer(inQueue_, BUFFER_NUM, maxTile * sizeof(T));
    pipe->InitBuffer(outQueue_, BUFFER_NUM, TILE_K * TILE_N * sizeof(T));

    pipe->InitBuffer(x1Fp32Buf_, TILE_K * sizeof(float));
    pipe->InitBuffer(x2Fp32Buf_, TILE_N * sizeof(float));
    pipe->InitBuffer(tmpBuf_, TILE_N * sizeof(float));
    pipe->InitBuffer(accBuf_, TILE_K * TILE_N * sizeof(float));

    if constexpr (!std::is_same_v<T, float>) {
        pipe->InitBuffer(castBuf_, TILE_K * TILE_N * sizeof(T));
    }
}

template <typename T>
__aicore__ inline void KernelMulAddn<T>::Process() {
    int32_t endB = coreStartB_ + tiling_.chunkB;
    if (endB > tiling_.B) endB = tiling_.B;

    for (int32_t b = coreStartB_; b < endB; b++) {
        for (int32_t kb = 0; kb < KBlocks_; kb++) {
            int32_t k0 = kb * TILE_K;
            int32_t k1 = k0 + TILE_K;
            if (k1 > tiling_.K) k1 = tiling_.K;
            int32_t curK = k1 - k0;

            for (int32_t nb = 0; nb < NBlocks_; nb++) {
                int32_t n0 = nb * TILE_N;
                int32_t n1 = n0 + TILE_N;
                if (n1 > tiling_.N) n1 = tiling_.N;
                int32_t curN = n1 - n0;

                ComputeTile(b, k0, n0, curK, curN);
            }
        }
    }
}

template <typename T>
__aicore__ inline void KernelMulAddn<T>::ComputeTile(int32_t b, int32_t k0, int32_t n0,
                                                      int32_t curK, int32_t curN) {
    // Get local tensors from TBuf
    AscendC::LocalTensor<float> x1Fp32 = x1Fp32Buf_.Get<float>(curK);
    AscendC::LocalTensor<float> x2Fp32 = x2Fp32Buf_.Get<float>(curN);
    AscendC::LocalTensor<float> tmpFp32 = tmpBuf_.Get<float>(curN);
    AscendC::LocalTensor<float> accFp32 = accBuf_.Get<float>(curK * curN);

    // Initialize accumulator to zero
    AscendC::Duplicate<float>(accFp32, 0.0f, curK * curN);

    // Outer-product accumulate over n tensor pairs
    for (int32_t i = 0; i < tiling_.n; i++) {
        // ---- Load x1[i, b, k0:k0+curK, 0] ----
        AscendC::LocalTensor<T> x1Local = inQueue_.AllocTensor<T>();
        int64_t x1Off = static_cast<int64_t>(i) * tiling_.B * tiling_.K
                      + static_cast<int64_t>(b) * tiling_.K + k0;
        AscendC::DataCopyParams x1Copy = {
            1, static_cast<uint16_t>(curK * sizeof(T) / AscendC::DEFAULT_C0_SIZE), 0, 0};
        AscendC::DataCopyPadExtParams<T> x1Pad = {false, 0, 0, 0};
        AscendC::DataCopyPad(x1Local, x1Gm_[x1Off], x1Copy, x1Pad);
        inQueue_.EnQue(x1Local);
        AscendC::LocalTensor<T> x1Deq = inQueue_.DeQue<T>();

        if constexpr (std::is_same_v<T, float>) {
            AscendC::DataCopy(x1Fp32, x1Deq, curK);
        } else {
            AscendC::Cast(x1Fp32, x1Deq, AscendC::RoundMode::CAST_NONE, curK);
        }
        inQueue_.FreeTensor(x1Deq);

        // ---- Load x2[i, b, 0, n0:n0+curN] ----
        AscendC::LocalTensor<T> x2Local = inQueue_.AllocTensor<T>();
        int64_t x2Off = static_cast<int64_t>(i) * tiling_.B * tiling_.N
                      + static_cast<int64_t>(b) * tiling_.N + n0;
        AscendC::DataCopyParams x2Copy = {
            1, static_cast<uint16_t>(curN * sizeof(T) / AscendC::DEFAULT_C0_SIZE), 0, 0};
        AscendC::DataCopyPadExtParams<T> x2Pad = {false, 0, 0, 0};
        AscendC::DataCopyPad(x2Local, x2Gm_[x2Off], x2Copy, x2Pad);
        inQueue_.EnQue(x2Local);
        AscendC::LocalTensor<T> x2Deq = inQueue_.DeQue<T>();

        if constexpr (std::is_same_v<T, float>) {
            AscendC::DataCopy(x2Fp32, x2Deq, curN);
        } else {
            AscendC::Cast(x2Fp32, x2Deq, AscendC::RoundMode::CAST_NONE, curN);
        }
        inQueue_.FreeTensor(x2Deq);

        // ---- Outer product: acc[k,:] += x1[k] * x2[:] ----
        for (int32_t k = 0; k < curK; k++) {
            float s = x1Fp32.GetValue(k);
            AscendC::Muls(tmpFp32, x2Fp32, s, curN);
            AscendC::Add(accFp32[k * curN], accFp32[k * curN], tmpFp32, curN);
        }
    }

    // ---- Write output[b, k0:k0+curK, n0:n0+curN] ----
    int64_t outOff = static_cast<int64_t>(b) * tiling_.K * tiling_.N
                   + static_cast<int64_t>(k0) * tiling_.N + n0;

    AscendC::LocalTensor<T> outLocal = outQueue_.AllocTensor<T>();
    AscendC::LocalTensor<T> castLocal;

    if constexpr (std::is_same_v<T, float>) {
        AscendC::DataCopy(outLocal, accFp32, curK * curN);
    } else {
        castLocal = castBuf_.Get<T>(curK * curN);
        AscendC::Cast(castLocal, accFp32, AscendC::RoundMode::CAST_ROUND, curK * curN);
        AscendC::DataCopy(outLocal, castLocal, curK * curN);
    }

    outQueue_.EnQue(outLocal);
    AscendC::LocalTensor<T> outDeq = outQueue_.DeQue<T>();

    // Row-by-row DataCopyPad to handle stride (tail tile may have N stride gap)
    for (int32_t kr = 0; kr < curK; kr++) {
        AscendC::DataCopyParams rowCopy = {
            1, static_cast<uint16_t>(curN * sizeof(T) / AscendC::DEFAULT_C0_SIZE), 0, 0};
        AscendC::DataCopy(outGm_[outOff + kr * tiling_.N],
                          outDeq[kr * curN], rowCopy);
    }
    outQueue_.FreeTensor(outDeq);
}

// ---- Kernel entry points for each dtype ----

extern "C" __global__ __aicore__ void mul_addn_half(GM_ADDR x1, GM_ADDR x2, GM_ADDR out,
                                                     GM_ADDR tiling) {
    AscendC::TPipe pipe;
    KernelMulAddn<half> kernel;
    kernel.Init(x1, x2, out, tiling, &pipe);
    kernel.Process();
}

extern "C" __global__ __aicore__ void mul_addn_bfloat16(GM_ADDR x1, GM_ADDR x2, GM_ADDR out,
                                                         GM_ADDR tiling) {
    AscendC::TPipe pipe;
    KernelMulAddn<bfloat16_t> kernel;
    kernel.Init(x1, x2, out, tiling, &pipe);
    kernel.Process();
}

extern "C" __global__ __aicore__ void mul_addn_float(GM_ADDR x1, GM_ADDR x2, GM_ADDR out,
                                                      GM_ADDR tiling) {
    AscendC::TPipe pipe;
    KernelMulAddn<float> kernel;
    kernel.Init(x1, x2, out, tiling, &pipe);
    kernel.Process();
}
