#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_mul_addn_half.h"
#include "aclrtlaunch_mul_addn_bfloat16.h"
#include "aclrtlaunch_mul_addn_float.h"

namespace ascend_kernel {

#pragma pack(push, 8)
struct MulAddnTiling {
    int32_t B;
    int32_t K;
    int32_t N;
    int32_t n;
    int32_t chunkB;
};
#pragma pack(pop)

at::Tensor mul_addn(const at::Tensor &x1, const at::Tensor &x2, int64_t n) {
    // x1: [n, B, K], x2: [n, B, N]
    TORCH_CHECK(x1.dim() == 3, "mul_addn: x1 must be 3-dimensional [n, B, K]");
    TORCH_CHECK(x2.dim() == 3, "mul_addn: x2 must be 3-dimensional [n, B, N]");
    TORCH_CHECK(x1.scalar_type() == x2.scalar_type(),
                "mul_addn: x1 and x2 must have same dtype");

    int32_t Bval = static_cast<int32_t>(x1.size(1));
    int32_t Kval = static_cast<int32_t>(x1.size(2));
    int32_t Nval = static_cast<int32_t>(x2.size(2));
    int32_t nVal = static_cast<int32_t>(n);

    // Determine core count
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Allocate output: [B, K, N]
    at::Tensor out = at::empty({static_cast<int64_t>(Bval),
                                 static_cast<int64_t>(Kval),
                                 static_cast<int64_t>(Nval)},
                                at::device(at::kPrivateUse1).dtype(x1.scalar_type()));

    // Tiling: split B dimension across cores
    // Use min(coreNum, B) cores to avoid idle cores
    int32_t usedCoreNum = static_cast<int32_t>(coreNum);
    if (usedCoreNum > Bval) usedCoreNum = Bval;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int32_t chunkB = (Bval + usedCoreNum - 1) / usedCoreNum;

    // Create tiling data
    at::Tensor tilingCpu = at::empty({static_cast<int64_t>(sizeof(MulAddnTiling))},
                                      at::device(at::kCPU).dtype(at::kByte));
    auto *tilingPtr = reinterpret_cast<MulAddnTiling *>(tilingCpu.data_ptr());
    tilingPtr->B = Bval;
    tilingPtr->K = Kval;
    tilingPtr->N = Nval;
    tilingPtr->n = nVal;
    tilingPtr->chunkB = chunkB;

    at::Tensor tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Ensure x1 and x2 are contiguous on NPU
    at::Tensor x1Npu = x1.contiguous();
    at::Tensor x2Npu = x2.contiguous();

    int64_t blockDim = static_cast<int64_t>(usedCoreNum);

    // Launch kernel based on dtype
    if (x1.scalar_type() == at::kHalf) {
        EXEC_KERNEL_CMD(mul_addn_half, blockDim, x1Npu, x2Npu, out, tilingNpu);
    } else if (x1.scalar_type() == at::kBFloat16) {
        EXEC_KERNEL_CMD(mul_addn_bfloat16, blockDim, x1Npu, x2Npu, out, tilingNpu);
    } else if (x1.scalar_type() == at::kFloat) {
        EXEC_KERNEL_CMD(mul_addn_float, blockDim, x1Npu, x2Npu, out, tilingNpu);
    } else {
        TORCH_CHECK(false, "mul_addn: unsupported dtype, expected float16/bfloat16/float32");
    }

    return out;
}

} // namespace ascend_kernel
